package spec
import("bytes";"encoding/json";"errors";"fmt";"io";"os")
const SchemaV1="ohf.experiment.v1"
type ExperimentSpec struct{Schema string `json:"schema"`;ID string `json:"id"`;Baseline string `json:"baseline"`;Campaign string `json:"campaign"`;Seed SeedSpec `json:"seed"`;Source SourceSpec `json:"source"`;Renderer RendererSpec `json:"renderer"`;Variants int `json:"variants"`;Degradations []string `json:"degradations"`;Evaluators []string `json:"evaluators"`};type SeedSpec struct{Algorithm string `json:"algorithm"`;Value uint64 `json:"value"`};type SourceSpec struct{Kind string `json:"kind"`;Generator string `json:"generator"`;Length int `json:"length"`};type RendererSpec struct{ID string `json:"id"`;Version string `json:"version"`;Width int `json:"width"`;Height int `json:"height"`}
func Load(path string)(ExperimentSpec,error){b,err:=os.ReadFile(path);if err!=nil{return ExperimentSpec{},err};dec:=json.NewDecoder(bytes.NewReader(b));dec.DisallowUnknownFields();var s ExperimentSpec;if err:=dec.Decode(&s);err!=nil{return ExperimentSpec{},fmt.Errorf("decode spec: %w",err)};var trailing any;if err:=dec.Decode(&trailing);err!=io.EOF{if err==nil{return ExperimentSpec{},errors.New("decode spec: trailing JSON content")};return ExperimentSpec{},fmt.Errorf("decode spec: trailing content: %w",err)};if err:=s.Validate();err!=nil{return ExperimentSpec{},err};return s,nil}
func(s ExperimentSpec)Validate()error{if s.Schema!=SchemaV1{return fmt.Errorf("schema: expected %q, got %q",SchemaV1,s.Schema)};if s.ID==""{return errors.New("id: required")};if s.Baseline!="R3.10"{return fmt.Errorf("baseline: F1 accepts only R3.10, got %q",s.Baseline)};if s.Campaign==""{return errors.New("campaign: required")};if s.Seed.Algorithm!="splitmix64-v1"{return fmt.Errorf("seed.algorithm: unsupported %q",s.Seed.Algorithm)};if s.Source.Kind!="synthetic"{return fmt.Errorf("source.kind: F1 supports only synthetic, got %q",s.Source.Kind)};if s.Source.Generator!="fixed-bytes-v1"{return fmt.Errorf("source.generator: F1 supports only fixed-bytes-v1, got %q",s.Source.Generator)};if s.Source.Length<=0{return errors.New("source.length: must be > 0")};if s.Renderer.ID==""||s.Renderer.Version==""{return errors.New("renderer.id and renderer.version: required")};if s.Renderer.Width<=0||s.Renderer.Height<=0{return errors.New("renderer.width and renderer.height: must be > 0")};if s.Variants<=0{return errors.New("variants: must be > 0")};if len(s.Evaluators)==0{return errors.New("evaluators: at least one evaluator required")};for _,e:=range s.Evaluators{if e!="computational"&&e!="native"{return fmt.Errorf("evaluators: unsupported %q",e)}};return nil}
